    # other members
    for orig_name in dir(subject):
        try:
            value = attrgetter(subject, orig_name)
            if ismock(value):
                value = undecorate(value)

            unmangled = unmangle(subject, orig_name)
            if unmangled and unmangled not in members:
                if orig_name in obj_dict:
                    # unwrap classmethod-wrapped properties (Python 3.9+)
                    raw = obj_dict.get(orig_name)
                    try:
                        if isinstance(raw, classmethod) and isinstance(raw.__func__, property):
                            value = raw.__func__
                    except Exception:
                        pass
                    members[unmangled] = ObjectMember(unmangled, value, class_=subject)
                else:
                    members[unmangled] = ObjectMember(unmangled, value)
        except AttributeError:
            continue

